export const profiles={tof:{name:'ToF · frontal',range:3,fov:.18,noise:.02},lidar:{name:'LiDAR · 360°',range:7,fov:Math.PI*2,noise:.04},ultrasonic:{name:'Ultrasónico',range:4,fov:.65,noise:.10},camera:{name:'Cámara · profundidad idealizada',range:6,fov:1.25,noise:.15}};
export const obstacles=[{x:3,y:2,r:.65},{x:7,y:3,r:.8},{x:5,y:6,r:.6},{x:9,y:7,r:.75},{x:2,y:8,r:.55}];
export const beacons=[{x:3,y:5},{x:8,y:1.5},{x:10,y:9}];
export function raycast(x,y,a,max,objects=obstacles){let best=max;const dx=Math.cos(a),dy=Math.sin(a);for(const o of objects){const ox=x-o.x,oy=y-o.y,b=ox*dx+oy*dy,c=ox*ox+oy*oy-o.r*o.r,d=b*b-c;if(d>=0){const t=-b-Math.sqrt(d);if(t>=0)best=Math.min(best,t);}}for(const [p,v] of [[x,dx],[y,dy]])if(Math.abs(v)>1e-8){const t=((v>0?12:0)-p)/v;if(t>=0)best=Math.min(best,t);}return best;}
export function createState(){return {x:1,y:1,a:.35,v:0,pitch:0,rate:0,integral:0,control:0,time:0,battery:100,state:'DISARMED',link:true,stop:false,score:0,hits:0,visited:[],path:[]};}
export function step(s,input,dt){dt=Math.min(.05,Math.max(0,dt));s.time+=dt;const active=!s.stop&&s.state!=='FAULT'&&s.state!=='DISARMED';const target=active&&s.link?Math.max(-1,Math.min(1,input.forward))*1.5:0;s.v+=(target-s.v)*Math.min(1,dt*4);if(!active)s.v=0;s.a+=(active&&s.link?input.turn:0)*dt*1.8;const nx=s.x+Math.cos(s.a)*s.v*dt,ny=s.y+Math.sin(s.a)*s.v*dt;const collision=nx<.22||ny<.22||nx>11.78||ny>11.78||obstacles.some(o=>Math.hypot(nx-o.x,ny-o.y)<o.r+.22);if(collision&&Math.abs(s.v)>.02){s.v=0;s.hits++;s.score=Math.max(0,s.score-5);}else{s.x=nx;s.y=ny;}if(active){const gains=input.pid||{kp:34,ki:0,kd:6};s.integral=Math.max(-.5,Math.min(.5,s.integral-s.pitch*dt));s.control=Math.max(-20,Math.min(20,-gains.kp*s.pitch+gains.ki*s.integral-gains.kd*s.rate));s.rate+=(10*s.pitch+s.control+target*.4)*dt;s.pitch+=s.rate*dt;s.battery=Math.max(0,s.battery-dt*.025);s.state=target?'TELEOP':'BALANCING';}if(Math.abs(s.pitch)>.65||s.battery===0){s.state='FAULT';s.v=0;}for(let i=0;i<beacons.length;i++)if(!s.visited.includes(i)&&Math.hypot(s.x-beacons[i].x,s.y-beacons[i].y)<.65){s.visited.push(i);s.score+=100;}return s;}
export function sense(s,key,noise=1,random=Math.random){const p=profiles[key];const rays=key==='lidar'?72:17;return Array.from({length:rays},(_,i)=>{const a=s.a-p.fov/2+p.fov*i/(rays-1),truth=raycast(s.x,s.y,a,p.range);return {a,d:Math.max(0,Math.min(p.range,truth+(random()-.5)*2*p.noise*noise)),hit:truth<p.range};});}
